        state: [E(.digital, 3, "911 Call", "{D} reports the truck stolen from the casino."), E(.document, 2, "Repossession Order", "Issued two days earlier."), E(.physical, 2, "Truck", "Found in a relative's barn with the plates removed.")],
        defense: [E(.statement, 1, "Left at the Casino", "{DL} says the truck was left at the casino."), E(.statement, 1, "Believed Stolen", "{DL} says {D.he} thought it was gone.")],
