    static let roadBlockadeV1 = SmallCases.make(
        key: "story.roadBlockade",
        category: .violent,
        headlines: ["Nurse Driving to Patient Hits Protester After Crowd Closes Around Car", "Sign Pole Strikes Windshield Before Car Surges"],
