        spec: "Assaulted {V} with a motor vehicle, a deadly weapon, inflicting serious injury, on {DATE}.",
        ages: 30...60,
        victim: true,
        summary: "On {DATE}, about forty protesters blocked a road. {D}, a home health nurse on the way to a patient, stopped, then inched forward as protesters surrounded the car. Someone struck the windshield with a sign pole and the car surged, hitting {V}, who suffered a broken leg. {DL} says {D.he} panicked and the pedal slipped.",
        state: [E(.video, 3, "Bystander Video", "The car moves forward into {V}."), E(.forensic, 2, "Medical Report", "A broken leg."), E(.physical, 1, "Windshield", "Cracked by a sign pole.")],
        defense: [E(.statement, 2, "Panic", "{DL} says {D.he} was surrounded and afraid.")],
        role: "Injured protester",
        exam: [.direct("Walk us through what you were doing that afternoon.", "\"I was one of about forty protesters on a county road at about four. We were standing across the lanes with signs, and traffic had backed up.\""), .direct("What did you see when the car arrived?", "\"A small sedan stopped in front of the crowd. The driver honked and waved at us to move.\""), .direct("What did the car do next?", "\"It inched forward as people moved toward it. Then someone struck the windshield with a sign pole, and the car surged.\""), .direct("How did you get hurt?", "\"The car hit my leg and knocked me down. I felt something snap and I couldn't get up.\""), .direct("What did the doctors tell you?", "\"I had a broken leg and needed surgery. I was in a cast for months.\""), .direct("What did you do afterward?", "\"A friend called an ambulance and someone filmed it. I told deputies what I saw.\""), .cross("Did someone hit the car before it moved?", "\"Yes. A person hit the windshield with a pole. I saw it crack.\""), .cross("Was the car moving slowly at first?", "\"Yes. It inched forward for several seconds before the surge.\""), .cross("Were people crowding around the car?", "\"Some were. It was close, and I was near the front.\""), .cross("Was the driver honking?", "\"Yes, a few times. I thought it was to tell us to move.\""), .cross("Did the driver stop after hitting you?", "\"The car stopped within a second or two, I think.\"")],
        theory: ("{D} drove into a crowd and hurt {V}.", "A driver who panicked when surrounded."),
        allocution: "\"I let it get out of hand. I'm ashamed.\"",
        truths: ("{DL} had been honking and told people to move.", "The pedal was floored for two seconds."),
        defendant: [.direct("Describe your job and why you were on that road for the jury.", "\"I'm a home health nurse. I was driving to a patient who needed care that afternoon, and the road was the fastest way.\""), .direct("What happened when you reached the protest?", "\"A crowd was standing across the road. I stopped and honked to ask them to let me through.\""), .direct("How did the crowd react?", "\"People moved closer to the car. Some banged on the hood, and I felt surrounded.\""), .direct("What happened to the windshield?", "\"Someone hit it with a pole and it cracked. I was terrified and my foot pressed the pedal.\""), .direct("What did you do after the car moved?", "\"I stopped as soon as I could. I got out to see who was hurt and I called for help.\""), .direct("How has this affected you?", "\"If I am honest, I feel awful. I never meant to hurt anyone, and I think about it every day.\""), .cross("The car hit {V}. Isn't it your responsibility?", "\"I was driving, so yes. I didn't mean it, but I'm the one who hit {V.him}.\""), .cross("You honked and told people to move. Doesn't that show impatience?", "\"It shows I wanted to leave. I was afraid and I needed to get to a patient.\""), .cross("The pedal was down for two seconds. How is that a slip?", "\"I panicked. My foot pressed down and I didn't release.\""), .cross("You could have put the car in park. Why didn't you?", "\"I wasn't thinking. I was trying to get away from people hitting the car.\""), .cross("You were on your way to a patient. Was it an emergency?", "\"It was a scheduled visit. I was late and I wanted to get through.\"")],
        openings: ("About forty protesters blocked a county road. {D}'s car inched forward, someone struck the windshield with a sign pole, and the car surged into {V}, who suffered a broken leg.", "{D} was a home health nurse on the way to a patient who found {D.himself} surrounded and afraid. Jurors will hear that a cracked windshield and a panicked foot are not an intent to hurt."),
        closings: ("A bystander's video shows the car moving into {V}, and a doctor's report shows a broken leg. {D} was behind the wheel and pressed the pedal.", "A blockade, a crowd around a car, a windshield struck with a pole, and a driver who panicked. The State must show {D} meant to hurt anyone, and the video shows fear."),
