        identified: "A bystander video.",
        mood: .divided,
        doctrines: ["selfDefense", "burdenOfProof"])

    static let usedCarScamV1 = SmallCases.make(
        key: "story.usedCarScam",
        category: .whiteCollar,
        headlines: ["Pickup Sold With a Lien the Seller Never Mentioned, Repossessed Two Weeks Later", "Lender's Notice and Bill of Sale Tell Different Stories"],
        law: "falsePretenses",
        spec: "Obtained $5,200 from {V} by false pretenses, on {DATE}.",
        ages: 21...55,
        victim: true,
        summary: "{V} paid {D} $5,200 on {DATE} for a used pickup {D} advertised as 'paid off, clean title.' {D} said the paperwork would follow at the motor vehicles office. Two weeks later a tow truck took the pickup: {D} still owed the lender $7,400 and had missed four payments. The lender's notice listed the lien. {DL} says {D.he} meant to pay it off and expected to catch up.",
        state: [E(.document, 3, "Bill of Sale", "Signed by {D}: 'paid off, clean title.'"), E(.document, 3, "Lender Notice", "Four missed payments and a lien of $7,400."), E(.digital, 2, "Advertisement", "'Clean title, no liens' in {D}'s own listing."), E(.digital, 1, "Texts", "{D} dodges {V}'s questions about the title.")],
        defense: [E(.statement, 1, "Meant to Pay", "{DL} says {D.he} planned to pay off the lender."), E(.document, 1, "Partial Payment", "A $600 payment to the lender the week of the sale.")],
        role: "Buyer",
        exam: [.direct("Tell the jury what you were looking for and what you found.", "\"I wanted a used pickup for work. I found {D}'s listing, which said 'paid off, clean title, no liens.'\""), .direct("What did {D} tell you about the title?", "\"That the paperwork would follow at the motor vehicles office. I paid $5,200 and signed a bill of sale that repeated 'paid off, clean title.'\""), .direct("What happened two weeks later?", "\"A tow truck came to my driveway and took the pickup. The lender said {D} still owed $7,400 and had missed four payments.\""), .direct("What did the lender's notice say?", "\"It listed the lien and the missed payments. It said the pickup could be repossessed from anyone who held it.\""), .direct("What did you do?", "\"I texted {D} and asked about the title. {D} dodged my questions and then stopped answering.\""), .direct("How did the loss affect you?", "\"I lost $5,200 and had no truck. I couldn't get to work for a week.\""), .cross("Did you ask for the title at the sale?", "\"I did. {D} said it would be mailed and that the lender was handling it.\""), .cross("Did {D} make any payment to the lender around the sale?", "\"One of $600, the week of the sale.\""), .cross("Did you check the title before paying?", "\"I asked and was told it was clean. I didn't run a record check.\""), .cross("Did {D} offer a refund?", "\"No. {D} said it would take time.\""), .cross("Did {D} tell you about the missed payments?", "\"No. {D} never mentioned them.\"")],
        theory: ("{D} sold a truck with a lien while claiming a clean title.", "A seller who planned to pay the lender."),
        allocution: "\"It was wrong from the start, and I knew it.\"",
        truths: ("{DL} had missed four payments before the listing went up.", "{DL} had sold a car the same way a year earlier."),
        defendant: [.direct("What can you tell us about the pickup?", "\"I bought it two years ago with a loan from a lender. I'd fallen behind by four payments because of a job change.\""), .direct("What did you say in the listing?", "\"That it was paid off with a clean title. I wrote that because I planned to pay it off with the sale.\""), .direct("Why did you sell it?", "\"I needed money to catch up. I thought the sale would cover the loan.\""), .direct("What did you do with the money?", "\"I paid the lender $600 and kept the rest for rent. I meant to pay the balance when I could.\""), .direct("Why didn't you tell {V}?", "\"It would have lost the sale. I thought I could fix it before anyone noticed.\""), .direct("How are you coping with what happened?", "\"Sick. I took advantage of someone who trusted me, and I'm trying to make it right.\""), .cross("You advertised a clean title. Was that true?", "\"No. There was a lien of $7,400.\""), .cross("You sold a car the same way a year earlier. Isn't that a pattern?", "\"It was a different situation. I paid that one off.\""), .cross("You missed four payments before the listing. Didn't you know?", "\"I knew. I told myself I'd catch up.\""), .cross("You dodged {V}'s questions. Why?", "\"I was scared. I didn't know how to explain.\""), .cross("$600 on a $7,400 lien isn't paying it off. Is it?", "\"No. It was a start, and I should have been honest.\"")],
        openings: ("{D} advertised a used pickup as 'paid off, clean title, no liens,' took $5,200 from {V}, and two weeks later a tow truck came because {D} still owed the lender $7,400.", "{D} fell behind with the lender, planned to catch up with the sale, and paid $600 that week. Jurors will hear that a seller meant to pay the loan and was overwhelmed."),
        closings: ("A listing that says clean title, a bill of sale that repeats it, and a lender's notice for $7,400 and four missed payments. {V} lost $5,200 and a truck.", "A partial payment to the lender and a plan to catch up. The State must show {D} meant to deceive, and a seller who panicked is not the same as a scammer."),
        timeline: [(-30, "{D} falls behind with the lender."), (0, "{V} pays $5,200."), (1, "{V} asks again for the title."), (14, "The lender repossesses the truck."), (15, "{V} reports it.")],
        identified: "A lender's notice.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let garageBurglaryV1 = SmallCases.make(
        key: "story.garageBurglary",
