        state: [E(.forensic, 3, "Fingerprint", "{D}'s print on the interior door."), E(.video, 3, "Neighbor Camera", "A pickup with a dented tailgate at the garage."), E(.physical, 2, "Recovered Bicycles", "One bicycle found in {D}'s shed."), E(.statement, 1, "Neighbor", "Saw the truck leave at 3:20 p.m.")],
        defense: [E(.statement, 1, "Hired Hauler", "{DL} says a person asked {D.him} to haul scrap."), E(.statement, 1, "Permission", "{DL} says the door was open when {D.he} arrived.")],
        role: "Homeowner",
        exam: [.direct("Describe your family's Saturday for the jury.", "\"My family left for a youth football game at about one. We were gone until about five and came home to find the side door of the garage pried open.\""), .direct("What did you find inside?", "\"A generator and two bicycles were gone. The door to the house had been forced and items in the garage were disturbed.\""), .direct("How was the door forced?", "\"Pried off its latch with a flat tool. The frame was splintered where the latch had been.\""), .direct("What did the neighbor's camera show?", "\"A pickup with a toolbox and a dented tailgate backed up to the garage at about 2:50. It left at 3:20.\""), .direct("How did the deputy find {D}?", "\"The deputy saw a matching pickup at {D}'s house, and a fingerprint on the interior door matched {D}.\""), .direct("What did you recover?", "\"One bicycle was found in {D}'s shed. The generator and the other bike were not recovered.\""), .cross("Do you know {D}?", "\"No. I've never met {D}, and I've never hired anyone to haul scrap.\""), .cross("Was the door open when you left?", "\"No. I locked everything before we went to the game.\""), .cross("Did you see {D} at your home that day?", "\"No. I wasn't there.\""), .cross("Could {D}'s print have come from an earlier visit?", "\"I've never had {D} inside my home. I don't see how.\""), .cross("Did you post a request for scrap hauling?", "\"No. I don't have any scrap.\"")],
        theory: ("{D} broke into a home during a football game.", "A hauler who had permission."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} could not name who hired {D.him} to haul scrap.", "{DL} sold a generator that same week."),
        defendant: [.direct("Tell us about your work.", "\"I haul scrap and odd jobs with my truck. People call me for cleanouts and small moves.\""), .direct("Why were you at {V}'s house that afternoon?", "\"Someone called and said there was scrap to haul from a garage. I drove over and found the side door open.\""), .direct("Who hired you?", "\"A person who called and said to meet at the address. I didn't get a name, and the call came from a number I can't find.\""), .direct("Did you break the door?", "\"No. It was already open when I got there.\""), .direct("Why was your print on the interior door?", "\"I went in to look at the scrap and touched the door on the way. I didn't know it wasn't allowed.\""), .direct("How did a bicycle end up in your shed?", "\"I bought it from someone for $40 a few days later. The seller never said it came from a burglary.\""), .cross("You can't name who hired you. Isn't that convenient?", "\"It's not convenient. I'd tell you if I could.\""), .cross("You took a generator and sold one the same week. Isn't that a coincidence?", "\"I sold my own generator. I've done it before.\""), .cross("The door was pried. You say it was open. Which is it?", "\"It was open when I arrived. If it was pried, it was before I came.\""), .cross("Your truck matches the one on camera. How do you explain that?", "\"It's my truck, and I was there. I wasn't breaking in.\""), .cross("Why didn't you call anyone when you saw the damaged door?", "\"I thought it was the job. I'd been told it was a cleanout.\"")],
