        identified: "A neighbor's camera.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let parkingLotScreamV1 = SmallCases.make(
        key: "story.parkingLotScream",
        category: .publicOrder,
        headlines: ["Customer Screams at Dealership Service Advisor, Blocks Repair Lane for Fifteen Minutes", "Phone Video Posted Online Shows Cars Backed Up"],
