        defense: [E(.statement, 1, "Misexplained Warranty", "{DL} says the warranty was misexplained."), E(.statement, 1, "Rude Advisor", "{DL} says the advisor was rude.")],
        role: "Dealership manager",
        exam: [.direct("Tell the jury about your role at the dealership.", "\"I'm the dealership manager. I oversee sales and service, and I'm called when a customer dispute gets out of hand.\""), .direct("What happened at about ten that morning?", "\"{D} brought a car to the service department and demanded a free repair after a warranty claim was denied. The service advisor explained it wasn't covered.\""), .direct("How did {D} respond?", "\"{D} shouted at the advisor, followed the advisor outside, and stood in the service lane yelling that the dealership steals from customers.\""), .direct("What did blocking the lane do?", "\"It stopped cars from entering and leaving the service bay. Customers were waiting and employees couldn't move vehicles.\""), .direct("How many times did you ask {D} to move?", "\"Three. I asked politely, then firmly, and the third time I said I'd call deputies.\""), .direct("What did you do?", "\"At 10:30, I called the sheriff's office. Deputies arrived at about 10:40 and cited {D} for disorderly conduct.\""), .cross("Did {D} threaten anyone?", "\"No. {D} was loud and angry but didn't threaten violence.\""), .cross("Was the warranty claim in fact denied?", "\"Yes. It was denied after the advisor reviewed the contract.\""), .cross("Did the advisor explain the warranty clearly?", "\"I believe so. I wasn't there when the explanation was given.\""), .cross("Was {D} recording staff?", "\"Yes. {D} held up a phone and recorded the advisor.\""), .cross("Had {D} been told to leave before?", "\"Twice, and told to return with a written claim.\"")],
        theory: ("{D} blocked the service lane and screamed at staff.", "A customer upset over a denied warranty."),
        allocution: "\"I was angry and I made it everyone else's problem.\"",
