        truths: ("{DL} had made four returns in the past two weeks.", "{DL} pulled the receipt from a pocket before the clerk asked."),
        defendant: [.direct("Tell the jury about the appliances.", "\"A friend gave me a blender and a coffee maker as a gift, with a receipt. I did not need them, so I returned them.\""), .direct("Did you know the receipt was for other items?", "\"No. I did not. No one told me. I assumed the receipt matched.\""), .direct("Why did you pull the receipt out before the clerk asked?", "\"To save time. I do that at every store. It was a habit.\""), .direct("Why did you make other returns?", "\"I return things I do not need. It seemed harmless to me.\""), .direct("What about the thrift sticker?", "\"I did not notice it. The friend may have bought it at a thrift store.\""), .direct("How are you coping with what happened?", "\"I would say I feel embarrassed. I trusted a friend, and now I am accused of fraud.\""), .direct("What was going through your mind when the clerk gave you the store credit?", "\"I thought it was a normal return for a gift I did not need. I never imagined the receipt might belong to other items, and I felt shocked when the officer stopped me.\""), .cross("The serial numbers did not match the receipt, did they?", "\"No. I did not know. I thought they matched.\""), .cross("The blender had a thrift sticker, didn't it?", "\"Yes. I did not see it.\""), .cross("You made four returns in two weeks, didn't you?", "\"Yes. I return things I do not need.\""), .cross("You pulled the receipt out before the clerk asked, didn't you?", "\"Yes. It is a habit.\""), .cross("You received $284 in store credit, didn't you?", "\"Yes. I did. I would give it back.\"")],
        openings: ("A home goods store gave {D} $284 in store credit on {DATE} for a blender and a coffee maker with a receipt. A loss prevention officer noticed the serial numbers did not match the models on the receipt, the blender carried a thrift store price sticker, and the receipt belonged to a purchase of two other appliances.", "The defense will present appliances and a receipt that a friend gave {D} as a gift, and a person who did not know the receipt was for other items. A mistaken return is not a fraud."),
        closings: ("A receipt that lists different models, serial numbers that do not match, a thrift sticker on the blender, four returns in two weeks, and a receipt pulled before the clerk asked. The credit was $284.", "A gift from a friend and a receipt that no one said was wrong. The State has not proved that {D} knew the receipt was for other items."),
        timeline: [(-14, "The first return."), (-7, "A second return."), (0, "The return at the counter."), (0, "The loss prevention officer steps in."), (1, "A summons is issued.")],
        identified: "A returns audit.",
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let bikeRackTheftV1 = SmallCases.make(
        key: "story.bikeRackTheft",
        category: .property,
        headlines: ["E-Bike Disappears From Campus Rack, Lock Cut; Same Bike Seen on Resale Listing", "Security Video Shows Hooded Rider Pedaling Away"],
        law: "misdLarceny",
        spec: "Stole a bicycle valued at $900 belonging to {V}, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "{V} locked an electric bicycle worth $900 to a rack beside a lecture hall at 9 a.m. on {DATE}. When classes let out at 2 p.m. the cable lock was cut and the bike was gone. Campus security video showed a hooded rider cutting the lock and pedaling off. A week later {V} saw a resale listing with the same sticker on the frame from an account tied to {D}. {DL} says {D.he} bought the bike from a student for $300.",
        state: [E(.video, 3, "Security Video", "A hooded rider cuts the cable and leaves."), E(.digital, 3, "Resale Listing", "The same sticker on the frame, listed by {D}."), E(.document, 2, "Purchase Receipt", "{V}'s receipt and serial number."), E(.physical, 1, "Cut Lock", "Bolt cutter marks on the cable.")],
        defense: [E(.statement, 1, "Bought for $300", "{DL} says {D.he} paid $300 to a student."), E(.digital, 1, "Chat Log", "Messages with a seller named only 'Dylan'.")],
        role: "Bicycle owner",
        exam: [.direct("What happened to your electric bicycle on {DATE}?", "\"I locked it to the rack beside the lecture hall at nine in the morning. When classes let out at two, the cable was cut in two pieces and the bike was gone.\""), .direct("How did you secure the bike that morning?", "\"I ran a steel cable through the frame and the front wheel and locked it to the rack. I had used the same lock every day for months without a problem.\""), .direct("What did the campus security video show?", "\"A rider in a gray hood crouched at the rack, cut the cable with a bolt cutter in a few seconds, climbed on my bike, and pedaled away toward the street.\""), .direct("How did you find the resale listing a week later?", "\"A friend sent me a link to a marketplace page. The bike in the photos was mine, down to the scratch on the left pedal and the campus sticker on the frame.\""), .direct("What made you certain the bike in the listing was yours?", "\"The sticker sits right below the seat post in a spot I chose. The serial number on my purchase receipt matched the photo of the frame the seller posted.\""), .direct("What did you do after you saw the listing?", "\"I screenshotted it, saved the account name, and took everything to campus security and then to the sheriff's office with my receipt and the serial number.\""), .cross("The rider in the video never shows a face, correct?", "\"Correct. The hood stays up and the rider keeps a head down the whole time. I cannot tell you who is on the bike from that clip alone.\""), .cross("Other students got that same sticker, didn't they?", "\"Yes, the sticker was a giveaway at orientation, so plenty of bikes carry one. That is why I rely on the serial number and not just the sticker.\""), .cross("The listing asked $850 for a bike you paid $900 for, right?", "\"That is right. The price was a little under what I paid, so it looked like a fair market price and not a rock-bottom sale of a bike someone knew was stolen.\""), .cross("You never spoke to the person who posted the listing, did you?", "\"No. I did not message the seller because I was told to leave it to the deputies. All I know about the account comes from the page itself.\""), .cross("You cannot say who held the bike between the theft and the listing, can you?", "\"No. I only know it was gone at two o'clock and showed up a week later. Where it went in between is something I do not know.\"")],
        theory: ("{D} resold a stolen e-bike.", "A buyer who got a bargain."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had no receipt, only a chat with a seller who has since deleted the account.", "The listing price was $850."),
        defendant: [.direct("Where did you get the electric bicycle you listed online?", "\"I bought it from a student for $300 about a week before I listed it. We met in a parking lot near campus, and I paid cash for it on the spot.\""), .direct("Why did you pay so little for a bike like that?", "\"The seller said money was tight and needed cash for rent that week. Three hundred dollars seemed like a great deal, and I did not think hard about why it was so low.\""), .direct("What do you know about the seller?", "\"Only a first name, Dylan, and a chat account. We messaged back and forth to arrange the meeting, and the account was gone by the time I tried to reach out again.\""), .direct("Why did you list the bike for $850?", "\"I figured I could flip it for a profit. Used e-bikes sell for about that on campus, and I did not do any research beyond looking at a few similar listings.\""), .direct("How did the campus sticker end up in your listing photos?", "\"It was already on the frame when I bought it. I did not peel it off. I took pictures from every angle, and the sticker happened to be in the shot.\""), .direct("What did you do when you learned the bike might be stolen?", "\"I told the deputy everything I could remember and handed over the chat history. I wanted the bike returned to the owner and I did not argue with that.\""), .cross("You never asked the seller for a receipt or a title, did you?", "\"No, I did not. I should have asked, and I know that now. All I had was the chat and my word that I had paid for it.\""), .cross("You paid $300 for a bike that you listed at $850, correct?", "\"Yes. I thought I was getting a bargain, and I planned to keep part of the profit. I understand now that the price should have made me suspicious.\""), .cross("The seller's account is deleted, and you have no way to show the seller existed, do you?", "\"I have the chat messages I saved, but the account itself is gone. I understand that makes it hard to prove the seller was real.\""), .cross("The sticker on the frame matched the owner's bike, didn't it?", "\"Yes. I realized that when the deputy showed me the photos. I never saw the owner's bike before then, so I had no way of comparing.\""), .cross("You did not ask whether the lock had been cut before you bought it, did you?", "\"No. The bike came without a lock, and I did not question it. That was a mistake, and I should have asked what happened to the lock.\"")],
        openings: ("A locked bike was cut loose from a campus rack, and a week later the same bike appeared in an online listing posted by {D}. You will see the video, the sticker, and the serial number.", "{D} bought a used e-bike from a student for $300, listed it for resale, and had no idea it was stolen. This was a bargain hunt gone wrong, not a theft."),
        closings: ("The bike in the listing has {V}'s sticker and {V}'s serial number, and {D} posted it a week after it was cut loose. {D} paid far below value and cannot produce the seller.", "{D} saved the chat, answered every question, and wanted the bike returned. A deleted seller account and a low price are red flags in hindsight, but they are not proof that {D} stole anything."),
        timeline: [(0, "9 a.m.: {V} locks the bike."), (0, "2 p.m.: the lock is found cut."), (1, "Security video is pulled."), (7, "The resale listing appears."), (8, "The listing account is traced.")],
        identified: "A resale listing.",
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let badCheckFeedV1 = SmallCases.make(
        key: "story.badCheckFeed",
        category: .whiteCollar,
        headlines: ["Contractor's $1,150 Lumber Check Returned 'Account Closed,' Calls Go to Voicemail", "Bank Mailed Closure Notice to Wrong Suite"],
        law: "uttering",
        spec: "Uttered a check for $1,150 drawn on an account {D} knew was closed, to a lumber yard, on {DATE}.",
        ages: 28...66,
        victim: false,
        summary: "{D} wrote a $1,150 check to a lumber yard for framing lumber on {DATE}. The check came back marked 'account closed.' The bank had closed the account five months earlier after repeated overdrafts and mailed a notice. A lumber yard clerk left four messages. {DL} says the bank mailed the notice to an old suite and {D.he} believed the account was open.",
        state: [E(.document, 3, "Returned Check", "Marked 'account closed'."), E(.document, 2, "Bank Notice", "A closure notice mailed five months earlier."), E(.digital, 2, "Voicemails", "Four messages that went unreturned.")],
        defense: [E(.statement, 1, "Wrong Suite", "{DL} says the notice went to an old suite."), E(.digital, 1, "Text", "'Payment Friday' sent to the lumber yard.")],
        role: "Lumber yard clerk",
        exam: [.direct("What happened when the lumber yard deposited the check from {D}?", "\"It came back marked 'account closed' about a week later. The check was for $1,150 for framing lumber we had already loaded onto {D}'s truck.\""), .direct("What did {D} order and how was it handled that day?", "\"{D} bought a load of framing lumber on credit with a promise to pay by check. I wrote up the order, the crew loaded it, and {D} handed over the check on the spot.\""), .direct("How many times did you try to reach {D} after the check bounced?", "\"I left four voicemails over about two weeks, and each time I asked for a new form of payment. None of those messages was returned.\""), .direct("What did {D} say in the one text you received?", "\"A text came in that said 'Payment Friday.' No payment came that Friday or any Friday after it, and {D} never explained why.\""), .direct("Did {D} ever come back to the lumber yard?", "\"Once, a few days after the check bounced. {D} stood at the counter and said things would be sorted out soon, and then left without paying anything.\""), .direct("What did the yard do when the account stayed unpaid?", "\"We sent a written demand, filed a complaint with the sheriff's office, and kept the bounced check and the voicemails together with the order slip.\""), .cross("The text 'Payment Friday' was a promise to pay, wasn't it?", "\"Yes, that is how I read it. It was a promise to pay. I never received anything on Friday or afterward.\""), .cross("{D} did come to the yard in person once, correct?", "\"Yes. {D} stood at the counter and talked with me for a few minutes. It was a polite conversation, but nothing was paid that day.\""), .cross("You cannot say whether {D} ever saw the bank's closure notice, can you?", "\"No. I do not know what mail {D} received. I only know the check was returned for a closed account and nobody replied to the messages.\""), .cross("The lumber was delivered and was never returned, wasn't it?", "\"That is right. The lumber was built into a project, so it could not be returned. We were left with the unpaid bill for $1,150.\""), .cross("You sold lumber to {D} on credit based on {D}'s word, didn't you?", "\"Yes. We took the check at the time and trusted it. In hindsight we should have called the bank to confirm the account, but that is not how we normally do it.\"")],
        theory: ("{D} wrote a check on an account {D.he} knew was closed.", "A contractor who never got the bank's notice."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} had written six other checks on the closed account.", "{DL} still used the old checkbook."),
        defendant: [.direct("Did you know the account was closed when you wrote the check?", "\"No. I believed the account was still open. I had written checks on it for years, and I never saw anything saying it had been shut.\""), .direct("What did you do with mail from the bank that year?", "\"I had moved my office and the bank still had my old suite on file. Mail went to that address, and I did not check there as often as I should have.\""), .direct("What did you think when you got the voicemails from the yard?", "\"I thought I could cover it quickly and I kept putting off the call. I was busy with the job and I did not want to talk until I had the money.\""), .direct("What did you mean by the text that said 'Payment Friday'?", "\"I meant that I would have the money Friday. I thought a job payment would come in. It did not, and I should have told the yard that.\""), .direct("What did you do after you learned the account had been closed?", "\"I went to the bank and learned it had been closed for five months after repeated overdrafts. I tried to set up payment, but I could not cover it all.\""), .direct("What have you done about the unpaid lumber since the check bounced?", "\"I have offered the yard a payment plan and made a first payment. I know it does not undo the mistake, but I want to pay what I owe.\""), .cross("You wrote six other checks on that same account, didn't you?", "\"Yes. I wrote several checks on the account, and some of them also bounced. I was careless about tracking what was in it.\""), .cross("You kept using the old checkbook even after the bank closed the account, correct?", "\"I had a stack of the old checks and I kept using them. I did not realize the account was closed, and I did not look at a balance.\""), .cross("You ignored four voicemails from the lumber yard, didn't you?", "\"I did not return them right away. I was embarrassed and busy. I should have called back the first time, and I did not.\""), .cross("'Payment Friday' came and went and nothing was paid, correct?", "\"That is true. I thought I would have the money by then and I did not. I take responsibility for that.\""), .cross("A prudent contractor would check the account balance before writing a check for $1,150, wouldn't they?", "\"Yes, a careful one would. I did not do it that day, and I know that is a mistake I should not have made.\"")],
        openings: ("{D} wrote a $1,150 check to a lumber yard for framing lumber, and it came back marked 'account closed.' The bank had closed the account five months before, and had sent a notice.", "{D} wrote a check believing the account was open. The bank mailed its closure notice to an old suite, and {D} never saw it. That is a mistake, not a crime."),
        closings: ("The check came back for a closed account, four messages went unanswered, and a text promised payment that never came. A contractor who writes six checks on a closed account knew or should have known.", "{D} never saw the bank's notice because it went to the wrong suite, and {D} did not know the account was closed. {D} wrote a check believing it was good."),
        timeline: [(-150, "The bank closes the account."), (0, "{D} writes the check."), (3, "The check is returned."), (5, "The clerk leaves messages."), (10, "A complaint is filed.")],
        identified: "A returned check.",
        mood: .divided,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let apartmentFireV1 = SmallCases.make(
        key: "story.apartmentFire",
        category: .property,
        headlines: ["Rooming House Stairwell Fire at 4 A.M. Forces Out Eleven Residents", "Lighter Fluid Can Found Behind Dumpster, Former Tenant Seen Nearby"],
        law: "arson1",
        threshold: 7,
        spec: "Willfully and maliciously burned an occupied dwelling of {V}, a landlord, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "A fire started in the ground-floor stairwell of an eleven-room rooming house at 4 a.m. on {DATE}. Eleven residents escaped by a back fire escape; one was treated for smoke. The fire marshal found a container of lighter fluid behind a dumpster and a pour pattern on the steps. {D}, evicted from room 4 for unpaid rent three days earlier, had texted {V} that {V.he} 'would regret it.' A hardware store camera showed {D} buying lighter fluid at 11 p.m. {DL} says {D.he} bought it for a camping stove.",
        state: [E(.forensic, 3, "Fire Marshal", "Lighter fluid and a pour pattern on the stairs."), E(.digital, 2, "Threatening Text", "{D} tells {V} {V.he} 'will regret it.'"), E(.video, 3, "Hardware Store Camera", "{D} buys lighter fluid at 11 p.m."), E(.document, 1, "Eviction Notice", "Served three days before.")],
        defense: [E(.statement, 1, "Camping Stove", "{DL} says the fluid was for a camping stove."), E(.statement, 1, "At Relative's", "{DL} says {D.he} slept at a relative's.")],
        role: "Fire marshal",
        exam: [.direct("Where did the fire start in the rooming house?", "\"In the ground-floor stairwell, near the foot of the steps. That is the main way out of the building, so residents on the upper floors were cut off from the front door.\""), .direct("What did you find behind the dumpster?", "\"A container of lighter fluid, almost empty and still smelling of fuel. It was lying on its side in the shadow between the dumpster and the back wall.\""), .direct("What did the burn pattern tell you about how the fire was set?", "\"There was a pour pattern across the lower steps, with deep char where liquid had pooled. That points to a liquid accelerant poured and lit, not an electrical fault.\""), .direct("How did the residents get out of the building?", "\"By the back fire escape. Eleven people got out, and one was treated for smoke. Firefighters said the stairwell would have been impassable within minutes.\""), .direct("What did you learn about the tenant who had been evicted from room 4?", "\"{D} had been served an eviction notice three days earlier for unpaid rent. {D} had also sent a text to {V} saying {V.he} would regret it.\""), .direct("What did the hardware store camera show?", "\"{D} buying a can of lighter fluid at about eleven that night. The time was about five hours before the fire started in the stairwell.\""), .cross("Lighter fluid is sold at nearly every hardware store, isn't it?", "\"Yes, it is a very common product. Many households keep it for grilling, so finding it is not unusual in itself.\""), .cross("No lighter was found in {D}'s possession, correct?", "\"That is correct. We did not find a lighter or matches on {D}. I cannot tell you how the fluid was ignited.\""), .cross("You did not see who poured the fluid, did you?", "\"No. No one saw it poured. My conclusion comes from the pattern on the steps and the container found behind the dumpster.\""), .cross("The container behind the dumpster was never tied to {D} by a fingerprint, was it?", "\"The container was too wet and sooty to yield a print. I cannot connect it to {D} except through the store purchase and the timing.\""), .cross("A camping stove also uses lighter fluid, doesn't it?", "\"Some camp stoves run on liquid fuel. Lighter fluid is not usually recommended for that, but I know people sometimes use it.\"")],
        theory: ("{D} set fire to a rooming house after an eviction.", "A former tenant with a camping stove."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} was seen walking toward the rooming house at 3:50 a.m.", "{DL} had asked a roommate whether the fire escape was unlocked."),
        defendant: [.direct("Did you set the fire in the rooming house?", "\"No. I was angry about the eviction, but I did not set that fire. People lived in that building, and I would not put them at risk.\""), .direct("Why did you buy lighter fluid at eleven that night?", "\"I had a camping stove I planned to use because I had nowhere to stay. I wanted fuel for it, and the hardware store was still open.\""), .direct("Where did you spend the night of the fire?", "\"I slept at a relative's place across town. I got there late, and the relative was already in bed. I did not hear about the fire until morning.\""), .direct("Why were you seen walking toward the rooming house at 3:50 that morning?", "\"I was heading back to collect some of my things from room 4. I changed my mind when I saw how dark it was, and I turned around.\""), .direct("What did you mean by the text you sent to {V}?", "\"I was furious about being evicted and I wrote that {V.he} would regret it. I meant it as venting, not as a plan to hurt anyone.\""), .direct("What did you do when you heard about the fire?", "\"I went numb. I called my relative, then went to the scene to see if anyone was hurt. I was afraid people would blame me because of the eviction.\""), .cross("You asked a roommate whether the fire escape was unlocked, didn't you?", "\"I did. I was thinking about how to get my things out at night. I know how it sounds now, but I was not planning a fire.\""), .cross("You were walking toward the building at 3:50, just ten minutes before the fire, weren't you?", "\"I was walking in that direction. I turned around before I got to the building, and I did not go near the stairwell.\""), .cross("You bought the fuel, you sent the threat, and you were nearby. Is that a coincidence?", "\"It looks like one, but it is. I bought fuel for a stove, I vented in a text, and I walked around because I had nowhere to go.\""), .cross("You did not call anyone to confirm you slept at a relative's place, did you?", "\"I did not call anyone that night. The relative can say I was there when the sun came up, but I cannot show you a call.\""), .cross("You were angry at {V} and at the landlord, weren't you?", "\"Yes. I was angry about the eviction. I will not deny that. But anger is different from setting a fire where people sleep.\"")],
        openings: ("A fire started in the stairwell of a rooming house at 4 a.m., three days after {D} was evicted. A threatening text, a can of lighter fluid, and a camera put {D} close to the fire.", "{D} was evicted and angry, but anger is not arson. {D} bought fuel for a camping stove, slept at a relative's, and never set that fire."),
        closings: ("The eviction, the threat to {V}, the lighter fluid, and a walk toward the building at 3:50 all point to {D}. A pour pattern on the stairs shows the fire was set.", "No one saw {D} start the fire, no lighter was found, and a camping stove explains the fuel. Anger and bad timing are not proof of arson."),
        timeline: [(-3, "{D} is evicted."), (-1, "{D} sends the text."), (0, "11 p.m.: {D} buys lighter fluid."), (0, "4 a.m.: the fire."), (1, "The marshal's findings.")],
        identified: "A fire marshal's report.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let bearCubVideosV1 = SmallCases.make(
        key: "story.bearCubVideos",
        category: .violent,
        headlines: ["Two Teens Filmed Fox Kit Tormented After Capture From Den; Clips Went Up on Chat Group", "Wildlife Officer Traces Clips to a Rural Farm"],
        law: "animalCruelty",
        threshold: 7,
        spec: "Intentionally tortured an animal, a fox kit, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Two people filmed a fox kit being tormented near a den on {DATE} and posted the clips to a chat group. A member reported them to a wildlife officer. {D} appears in the video holding the kit. A necropsy of a kit found nearby showed injuries consistent with the video. {DL} says {D.he} was only recording and the other person did the harm.",
        state: [E(.video, 3, "Video", "{D} holds the kit in the clips."), E(.digital, 3, "Chat Group Posts", "The clips posted from {D}'s account."), E(.forensic, 2, "Necropsy", "Injuries consistent with the clips.")],
        defense: [E(.statement, 1, "Only Recording", "{DL} says {D.he} only recorded."), E(.statement, 1, "The Other Person", "{DL} says the other person hurt the kit.")],
        role: "Wildlife officer",
        exam: [.direct("What did the video show when you reviewed it?", "\"It showed {D} holding a fox kit in both hands while someone off camera moved in and out of the frame. The kit was frightened and squealing.\""), .direct("How did the clips come to your attention?", "\"A member of an online chat group saw the clips and contacted our office. We were able to see who posted them and trace the account back to {D}.\""), .direct("Who posted the clips to the chat group?", "\"{D}'s account posted all the clips, with a caption. The posts went up within an hour of the filming, so it appears they were shared right away.\""), .direct("What did the necropsy of the kit found nearby show?", "\"Injuries consistent with what the clips showed, including broken ribs and bruising. The kit had died of those injuries within a day or so of the filming.\""), .direct("What did you find at the den site?", "\"We found the den and signs that a kit had been taken from it. The ground matched a location visible in the background of the video.\""), .direct("What did {D} tell you when you spoke?", "\"{D} said {D.he} only filmed the other person and did not harm the kit. That is why we looked closely at the audio and the captions.\""), .cross("The video does not show {D} hurting the kit, does it?", "\"Not directly. {D} is shown holding the kit, but the harm in the clips is done by someone mostly outside the frame.\""), .cross("Another person appears in the clips, correct?", "\"Yes, a second person is heard and partly seen. We have not been able to identify that person with certainty.\""), .cross("Holding a kit is not the same as injuring it, is it?", "\"That is true, holding it is not the same as injuring it. I am telling you what the video and the audio show, taken together.\""), .cross("The necropsy cannot say who caused the injuries, can it?", "\"No. The necropsy tells us what the injuries were and when they likely happened. It cannot tell us which person caused them.\""), .cross("{D} cooperated when you came to talk, didn't {D.he}?", "\"{D} agreed to talk and answered questions. {D.he} was nervous, but I would not call it uncooperative.\"")],
        theory: ("{D} took part in tormenting a fox kit and posted the video.", "A bystander who recorded."),
        allocution: "\"I should have walked away.\"",
        truths: ("{DL} laughed on the audio and gave directions.", "{DL} captioned the post."),
        defendant: [.direct("Did you hurt the fox kit?", "\"No. I did not hurt it. I held it for a moment because I was asked to, and I let it go when I realized how frightened it was.\""), .direct("Why were you recording the video?", "\"It all happened fast and I pulled out my phone. I wanted to have something to show people. I did not think about what I was filming.\""), .direct("What was the other person doing during the filming?", "\"The other person was the one tossing and prodding the kit. I told them to stop, but they laughed, and I kept recording instead of leaving.\""), .direct("Why did you post the clips to the chat group?", "\"It was a stupid impulse. A few people in the group posted similar things, and I wanted to look funny. I regret it deeply.\""), .direct("What did you do after you realized the kit was hurt?", "\"I put it back near the den and went home feeling sick. I should have called a wildlife officer, and I did not.\""), .direct("What would you say now about posting those clips?", "\"It was wrong. I should not have filmed it, I should not have posted it, and I should have called someone to help the kit instead of standing there.\""), .cross("You laughed on the audio, didn't you?", "\"Yes, I did. It was a nervous laugh, but I know how it sounds on a recording. I am ashamed of it.\""), .cross("You gave directions to the other person during the filming, didn't you?", "\"I said things like 'hold it up.' I wanted a better shot. I did not think about it as telling someone to hurt the animal.\""), .cross("You wrote the caption on the post, didn't you?", "\"I did. I wrote it as a joke, and it was a bad one. I should not have written anything.\""), .cross("You posted the clips an hour after the filming, didn't you?", "\"Yes. I sent them right away. I did not think about what it meant to share them, and I deleted them when I understood.\""), .cross("You could have walked away at any time, couldn't you?", "\"Yes, I could have. I did not, and that is the part I cannot defend. I stood there and recorded.\"")],
        openings: ("Two people filmed a fox kit being tormented near its den, and the clips were posted by {D} with a caption. A necropsy showed injuries consistent with the video.", "{D} recorded a cruel scene and made a poor choice to post it. But {D} did not harm the kit. The person who did is not in this courtroom."),
        closings: ("{D} held the kit, laughed on the audio, wrote the caption, and posted the clips. A necropsy matched the injuries. {D} took part and showed it to the world.", "{D} did not hurt the kit and said so from the first conversation. Recording something terrible is not the same as doing it, and holding an animal is not abuse."),
        timeline: [(0, "Afternoon: the kit is taken from a den."), (0, "4 p.m.: the clips are filmed."), (0, "5 p.m.: the clips are posted."), (2, "A member reports it."), (3, "A wildlife officer contacts {D}.")],
        identified: "A video.",
        mood: .wantsConviction,
        doctrines: ["lesserIncluded"],
        genders: ["D": .male])

    static let benefitsOverreportV1 = SmallCases.make(
        key: "story.benefitsOverreport",
        category: .whiteCollar,
        headlines: ["Food Assistance Recipient Earned Restaurant Wages Never Reported, Agency Alleges", "Caseworker Says No One Said to Skip Reporting Wages"],
        law: "falsePretenses",
        spec: "Obtained $3,400 in food assistance benefits from {V}, a county agency, by false pretenses, on {DATE}.",
        ages: 22...55,
        victim: true,
        summary: "A county agency's fraud unit matched payroll data to benefit applications and found {D} had stated no income at eleven monthly renewals while working weekend shifts at a diner, which brought $3,400 in benefits that {D} would not otherwise have received. {DL} says a front desk clerk said wages from a tip-based job did not count.",
        state: [E(.document, 3, "Payroll Match", "Eleven months of diner pay stubs."), E(.document, 3, "Renewal Forms", "Each form says no income, signed by {D}.")],
        defense: [E(.statement, 1, "Front Desk Advice", "{DL} says a clerk said tips did not count.")],
        role: "County fraud investigator",
        exam: [.direct("What did you find when the county matched payroll data to the benefit file?", "\"{D} had reported no income at eleven monthly renewals, but payroll records showed weekend pay from a diner for each of those months.\""), .direct("What did the renewal forms say?", "\"Each form had a line for income, and each said none. All eleven were signed by {D} under a statement that the information was true and complete.\""), .direct("How much did the unreported pay affect the benefits {D} received?", "\"It brought about $3,400 in benefits that {D} would not have received if the income had been reported. That is the amount we calculated for the overpayment.\""), .direct("What did the diner's pay stubs show?", "\"Regular weekend shifts with an hourly wage and tips reported on the stubs. The totals were steady month to month, so it was not a one-time event.\""), .direct("How does the agency treat tip income?", "\"Tips count as income. The application packet says so in a list of income types, and the handout at the front desk lists tips by name.\""), .direct("What happened when you interviewed {D}?", "\"{D} said a clerk at the front desk told {D.him} that tip-based pay did not count. We looked for a record of that advice and did not find one.\""), .cross("The agency has no record of what the clerk told {D}, does it?", "\"No. The front desk does not log what is said to applicants. I cannot say what was or was not told to {D}.\""), .cross("The clerk {D} named no longer works for the agency, does {D.he}?", "\"That is correct. The clerk left some months ago, and we have not been able to ask about it.\""), .cross("Tip-based work can be confusing for applicants, can't it?", "\"It can be, which is why the packet lists tips as income. People sometimes misunderstand, but the form is clear that all income must be reported.\""), .cross("{D} did not hide the diner job when you asked about it, did {D.he}?", "\"No. {D} acknowledged the job at once in the interview. I did not have to pull teeth to learn about it.\""), .cross("The benefits were small and the amounts were modest, weren't they?", "\"The total was $3,400 over eleven months. That is not a large sum compared with other cases, but it still goes to the overpayment.\"")],
        theory: ("{D} signed forms hiding wages.", "An applicant who followed a clerk's advice."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} had been given a handout that listed tips as income.", "The clerk named by {DL} left the agency months ago."),
        defendant: [.direct("Did you sign the renewal forms that said you had no income?", "\"Yes, I did. I signed all eleven. I believed what I wrote at the time because a clerk had told me tips would not count.\""), .direct("What did the clerk say to you about tips?", "\"When I first applied, I asked whether tips mattered. The clerk said wages from a tip-based job did not count as income for the benefit.\""), .direct("Why did you work weekend shifts at the diner?", "\"The benefit did not cover my rent and groceries. I took weekend shifts to catch up on bills and to avoid falling further behind.\""), .direct("Did you read the handout that listed tips as income?", "\"I got it in a stack of papers and put it in a folder. I did not read it closely, and I should have.\""), .direct("What did you do when the fraud unit contacted you?", "\"I told them about the diner right away and about what the clerk had said. I wanted to fix it and offered to repay what I owed.\""), .direct("What changed after you learned the diner pay counted as income?", "\"I stopped taking the benefit, reported the diner pay going forward, and set up a repayment plan with the county for what I had been overpaid.\""), .cross("You never wrote down the clerk's name, did you?", "\"No, I did not. I did not know the clerk's name then. I remember the desk and the conversation, but not a name.\""), .cross("The handout said tips are income, didn't it?", "\"It did. I did not read it. I trusted what I was told at the desk, and I understand that was not enough.\""), .cross("You signed eleven forms, and each said no income, correct?", "\"Yes, I did. I kept signing the same answer each month without going back to ask. That is on me.\""), .cross("You knew you were being paid at the diner every weekend, didn't you?", "\"Yes, of course. I knew I was being paid. What I did not understand was whether tips counted as income for the benefit.\""), .cross("You could have asked the agency in writing whether your tips counted, couldn't you?", "\"Yes. I should have asked again in writing. I took the first answer and kept going, and I did not check.\"")],
        openings: ("The county's fraud unit matched payroll data to benefit applications and found that {D} reported no income at eleven renewals while working weekend shifts at a diner.", "{D} followed advice from a front-desk clerk who said tips did not count as income. That is a misunderstanding about the rules, not an intent to deceive."),
        closings: ("Eleven forms said no income, eleven months of pay stubs said otherwise, and {D} signed every renewal. The handout told {D} that tips are income, and {D} did not read it.", "{D} never hid the diner job, told the unit about it right away, and offered to repay. A clerk's bad advice, and not a scheme, is why the forms were wrong."),
        timeline: [(-330, "The first renewal."), (-30, "The data match runs."), (0, "The fraud unit opens a file."), (10, "{D} is interviewed.")],
        identified: "A payroll data match.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let overpassGraffitiV1 = SmallCases.make(
        key: "story.overpassGraffiti",
        category: .property,
        headlines: ["Public Works Crew Scrubs Giant Lettering From Interstate Bridge", "Spray Paint Cans in Trunk Match Colors on the Concrete"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a city bridge, causing damage of $1,100, on {DATE}.",
        ages: 18...25,
        victim: true,
        summary: "Public works found a bridge covered in large block letters on {DATE}. Cleanup cost $1,100. A highway camera showed a hooded figure on the walkway at 2 a.m. and a car parked on the ramp. A deputy found cans of matching paint in {D}'s trunk and a stencil on the back seat. {DL} says {D.he} was painting a permitted mural nearby and the cans were left from that job.",
        state: [E(.video, 3, "Highway Camera", "Hooded figure on the walkway at 2 a.m."), E(.physical, 3, "Spray Cans", "Paint matches the bridge, found in {D}'s trunk."), E(.document, 2, "Cleanup Invoice", "$1,100.")],
        defense: [E(.statement, 1, "Permitted Mural", "{DL} says the cans were from a mural job.")],
        role: "City public works supervisor",
        exam: [.direct("What did your crew find on the overpass on {DATE}?", "\"Large block letters across both rails of the walkway, in black and orange paint. The paint was fresh, and it had dripped down the concrete in several places.\""), .direct("How much did the cleanup cost the city?", "\"$1,100, which covered two days of labor, a pressure washer, and a solvent to lift the paint. We also had to repaint part of the rail.\""), .direct("What did the highway camera capture that night?", "\"A hooded figure on the walkway at about two in the morning, and a car parked on the ramp below with its hazard lights on.\""), .direct("What did the deputy find when the car was stopped?", "\"Several spray cans in the trunk with paint matching the colors on the bridge, and a stencil on the back seat cut into block letters.\""), .direct("How did the stencil compare with the lettering on the bridge?", "\"The stencil's letter shapes and spacing matched the lettering, including the same odd serif on the last letter and the same line breaks.\""), .direct("What is the city's process for approving murals on public structures?", "\"An applicant files a permit with public works, and we assign a wall. A permit lists the location and the dates, and the work must stay within them.\""), .cross("No mural permit is on file for this bridge, correct?", "\"Correct. No one has applied for a permit on this overpass. The permit {D} showed us was for a wall on the other side of town.\""), .cross("The permit {D} showed you was real, wasn't it?", "\"Yes, it was real. It was issued to {D} for a wall on a building about six miles from the overpass.\""), .cross("The figure on the walkway is in a hood and you cannot see a face, can you?", "\"That is correct. The face is not visible in the camera footage. We identified {D} through the car, the paint, and the stencil.\""), .cross("Spray paint is sold at many stores, isn't it?", "\"Yes. It is common, and cans in one color look like cans in the same color from any store. I cannot match a can to a shop.\""), .cross("Artists paint at night to avoid traffic and crowds, don't they?", "\"Some do. I have heard that from permitted artists as well. It is not unusual, and I would not read anything into the hour alone.\"")],
        theory: ("{D} painted a bridge at night.", "An artist with permission elsewhere."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had a stencil that matches the lettering.", "The permitted wall was six miles away."),
        defendant: [.direct("Did you paint the letters on the overpass?", "\"No. I did not paint that bridge. I had permission to paint a mural on a different wall, and that is what the paint in my trunk was for.\""), .direct("What was the permitted mural you were working on?", "\"A large mural on the side of a building across town. I had a permit from the city and I was working on it in the evenings.\""), .direct("Why were the cans still in your trunk that night?", "\"I was driving home after a long session at the wall. I had not unloaded my gear, and I was too tired to carry it all inside.\""), .direct("What was the stencil for?", "\"I use stencils for lettering on my murals. That one was cut for a sign I was making, and I did not use it on the bridge.\""), .direct("Why were you parked on the ramp near the overpass at 2 a.m.?", "\"I was lost. I took a wrong turn on my way home and pulled over to check my phone. I turned on my hazard lights while I looked.\""), .direct("What did you do when the deputy stopped you that night?", "\"I told the deputy about the permit and the mural, and I showed the paperwork. I let the deputy look in the trunk because I had nothing to hide.\""), .cross("The permitted wall was six miles from the overpass, wasn't it?", "\"Yes, about six miles. I was lost, and I understand how it sounds. I was not planning to paint anything on that bridge.\""), .cross("You paint at night, don't you?", "\"Yes, sometimes. It is cooler and there is less traffic. I have a permit for the wall I was working on, so I did not hide.\""), .cross("The stencil matches the lettering on the bridge, doesn't it?", "\"It looks similar, but the style is common. A lot of lettering uses the same shapes, and I did not paint the bridge.\""), .cross("You were on the ramp near the bridge at 2 a.m., and the paint matched, correct?", "\"I was on the ramp. The paint is a common color from a common brand. I understand why it looks bad, but I did not paint the bridge.\""), .cross("You did not call anyone to tell them where you were that night, did you?", "\"No. I was alone and I did not think I would need to prove where I was. I wish I had a way to show it.\"")],
        openings: ("Public works found a bridge covered in block letters. A highway camera showed a hooded figure at 2 a.m., and a deputy found matching paint and a stencil in {D}'s car.", "{D} is an artist with a permit for a mural across town. The cans and stencil in the car belong to that job. {D} was lost, not painting a bridge."),
        closings: ("No permit exists for this bridge, the paint matches the cans in {D}'s trunk, and the stencil matches the lettering. The camera put {D} at the scene at 2 a.m.", "{D} has a permit for a different wall, and the paint is a common brand. No one saw {D} paint the bridge, and the figure on the walkway has no face."),
        timeline: [(-1, "{D} buys paint."), (0, "2 a.m.: the walkway."), (0, "6 a.m.: the crew arrives."), (1, "A deputy checks the car.")],
        identified: "A highway camera.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let barEjectedShootingV1 = SmallCases.make(
        key: "story.barEjectedShooting",
        category: .violent,
        headlines: ["Doorman Dies After Ejected Patron Comes Back With Pistol Before Last Call", "Surveillance Shows Hour-Long Gap Between Ejection and Return"],
        law: "murder2",
        threshold: 9,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was working the door at a bar on {DATE} when {D}, ejected an hour earlier after a shoving match, walked back across the lot and fired. {V} died at the scene. A parking lot camera showed {D} leaving, going to a truck, and returning with a pistol. {DL} says {V} reached under {V.his} jacket first.",
        state: [E(.video, 3, "Parking Lot Camera", "{D} fetches a pistol and returns."), E(.forensic, 3, "Medical Examiner", "Fatal gunshot wounds to the chest."), E(.physical, 3, "Pistol and Casings", "The pistol found in {D}'s truck matches the casings.")],
        defense: [E(.statement, 1, "Reached First", "{DL} says {V} reached under a jacket.")],
        role: "Sheriff's detective",
        exam: [.direct("What did the parking lot camera show on the night of the shooting?", "\"It showed {D} walking away from the bar after being thrown out, going to a truck, and returning across the lot about forty minutes later with a pistol.\""), .direct("What was {V}'s job at the bar that night?", "\"{V} was working the door, checking IDs and keeping order. {V} had put {D} out about an hour before the shooting after a shoving match.\""), .direct("What did you find at the scene?", "\"{V} was down near the entrance with gunshot wounds to the chest. A radio was clipped to {V}'s jacket, and we recovered several shell casings nearby.\""), .direct("What was recovered from {D}'s truck?", "\"A pistol in the cab that matched the casings from the scene. Ballistics confirmed the casings and the bullets recovered at autopsy were fired from that gun.\""), .direct("What did the medical examiner conclude about the cause of death?", "\"{V} died of gunshot wounds to the chest. Death would have been very fast, and nothing at the scene suggested {V} could have been saved.\""), .direct("What did you learn from {D}'s phone?", "\"A text sent to a friend before the shooting that said 'I'm going to settle this.' It was sent while {D} was sitting in the truck.\""), .cross("Nothing was found on {V} that was a weapon, correct?", "\"That is correct. We searched {V} and the immediate area and found no weapon. We found a radio clipped to the jacket.\""), .cross("What was under {V}'s jacket when the body was examined?", "\"A two-way radio on a clip. It sits right at the chest, and it is the kind of thing a person might reach for in a hurry.\""), .cross("{D} was cooperative when taken into custody, wasn't {D.he}?", "\"{D} did not resist and gave a statement. {D.he} told us {D.he} thought {V} was reaching for a weapon, and I wrote that down.\""), .cross("{D} had been drinking that night, hadn't {D.he}?", "\"I believe so. {D} had been at the bar for several hours and was put out after a shoving match. I do not have a test result.\""), .cross("The confrontation was brief, wasn't it?", "\"It was short. The camera shows {D} crossing the lot and the shots within seconds. I cannot say what was said at the door.\"")],
        theory: ("{D} came back and shot the doorman.", "A frightened patron."),
        allocution: "\"I should have walked away.\"",
        truths: ("{DL} sat in the truck for forty minutes after the ejection.", "{DL} told a friend by text, 'I'm going to settle this.'"),
        defendant: [.direct("Did you shoot {V}?", "\"Yes. I fired. I have thought about that moment every night since, and I wish with everything in me that it had never happened.\""), .direct("Why did you go back to the bar after you were thrown out?", "\"I went back to my truck to get my jacket and to cool off. I had no plan to hurt anyone, and I was still angry about being put out.\""), .direct("What did you do in the truck for forty minutes?", "\"I sat there trying to calm down. I thought about driving home, and I did not. I sent a text to a friend saying I wanted to settle things.\""), .direct("What did you mean when you texted 'I'm going to settle this'?", "\"I meant I wanted to talk and clear the air with the bar. It was just talk, and I did not mean I would shoot anyone.\""), .direct("What did you see in the moment you fired?", "\"{V} moved a hand toward the jacket, and I thought {V.he} was reaching for a weapon. I panicked and fired, and I was wrong.\""), .direct("What do you want {V}'s family to know?", "\"That I am deeply sorry. I wish I could take it back, and I will carry what I did for the rest of my life.\""), .cross("You carried a pistol back across the lot toward a person who had thrown you out, didn't you?", "\"Yes, I did. I should have left it in the truck. I carried it and I made a terrible choice.\""), .cross("You sat in your truck for forty minutes after being put out, didn't you?", "\"Yes. I sat there, and I got angrier instead of calmer. I should have driven away, and I did not.\""), .cross("Nothing was found on {V} that was a weapon, correct?", "\"Correct. Nothing was found. I thought I saw a weapon, and I was wrong, and {V} paid for my mistake.\""), .cross("You told a friend you were going to settle it, didn't you?", "\"I did. I know how it reads now. I meant to talk, but I brought a gun, and I cannot explain that away.\""), .cross("You walked across the lot with a loaded pistol, and {V} was unarmed. Whose choice was that?", "\"Mine. It was my choice to bring the pistol and to fire. I cannot blame anyone else for what happened.\"")],
        openings: ("{V} was working the door at a bar when {D}, thrown out an hour earlier, came back across the lot with a pistol and fired. A camera and the casings tell the story.", "{D} did not plan to kill anyone. {D} believed {V} was reaching for a weapon and fired in a moment of fear. That is the difference between murder and a tragic mistake."),
        closings: ("{D} was thrown out, sat in a truck for forty minutes, texted that it would be settled, and came back with a pistol. {V} was unarmed. The camera and the casings tell the rest.", "{D} saw a hand move and believed {V} was reaching for a weapon. In a split second of fear, {D} fired. That fear was real, and it was mistaken."),
        timeline: [(-1, "The ejection."), (0, "The walk to the truck."), (0, "The shots."), (1, "The truck is searched.")],
        identified: "A parking lot camera.",
        mood: .wantsConviction,
        doctrines: ["selfDefense", "imperfectSelfDefense", "lesserIncluded"],
        genders: ["D": .male, "V": .male])
}
